    {
        _activeSection = section;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        _loading = true;
        StateHasChanged();

        try
        {
            switch (_activeSection)
            {
                case "Profile":
                    _savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfileFields();
                    break;
                case "Notifications":
                    _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    _emailNotifications = _notificationPrefs.EmailNotifications;
                    _pushNotifications = _notificationPrefs.PushNotifications;
                    _weeklyDigest = _notificationPrefs.WeeklyDigest;
                    _mutedChannels = new List<string>(_notificationPrefs.MutedChannels);
                    break;
                case "Security":
                    _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    _changePasswordExpanded = false;
