    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _sessionToRevoke;
    private bool _showRevokeConfirm;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly List<string> _languages = new() { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        _loading = true;
        StateHasChanged();

        try
        {
            switch (_activeSection)
            {
                case "Profile":
                    _savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfileFields();
                    break;
                case "Notifications":
                    _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    _emailNotifications = _notificationPrefs.EmailNotifications;
                    _pushNotifications = _notificationPrefs.PushNotifications;
                    _weeklyDigest = _notificationPrefs.WeeklyDigest;
                    _mutedChannels = new List<string>(_notificationPrefs.MutedChannels);
                    break;
                case "Security":
                    _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    _changePasswordExpanded = false;
                    _currentPassword = "";
                    _newPassword = "";
                    _confirmPassword = "";
                    break;
                case "Appearance":
                    _appearanceSettings = await SettingsService.GetAppearanceAsync();
                    _theme = _appearanceSettings.Theme;
                    _fontSize = _appearanceSettings.FontSize;
                    _language = _appearanceSettings.Language;
                    _compactMode = _appearanceSettings.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", isError: true);
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private void ResetProfileFields()
    {
        if (_savedProfile is not null)
        {
            _displayName = _savedProfile.DisplayName;
            _email = _savedProfile.Email;
            _bio = _savedProfile.Bio;
            _avatarUrl = _savedProfile.AvatarUrl;
        }
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.");
    }

    // Notifications actions
    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(string channel, ChangeEventArgs e)
    {
        var muted = (bool)(e.Value ?? false);
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", isError: true);
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("New password cannot be empty.", isError: true);
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            ShowToast($"Error: {ex.Message}", isError: true);
        }
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirm = true;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirm = false;
            _sessionToRevoke = null;
            ShowToast("Session revoked.");
        }
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        ShowToast("Appearance settings saved!");
    }

    // Toast helper
    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastTimer?.Dispose();
        _toastTimer = new System.Timers.Timer(3000);
        _toastTimer.Elapsed += (_, _) =>
        {
            _toastMessage = null;
            _toastTimer?.Dispose();
            InvokeAsync(StateHasChanged);
        };
        _toastTimer.AutoReset = false;
        _toastTimer.Start();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // Render fragments
    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-display">@_avatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" class="form-input" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" class="form-input" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_bio" class="form-input form-textarea" rows="4"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannelMute(channel, e)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security Settings</h2>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="panel-toggle">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" class="form-input" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" class="form-input" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-input" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="two-factor-section">
                <label class="toggle-label">
                    <input type="checkbox" checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(_securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                        @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                    </span>
                </label>
                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="last-changed">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <h3>Active Sessions</h3>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions[0])
                                        {
                                            <button class="btn btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-session-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Confirm Session Revocation</h4>
                        <p>Are you sure you want to revoke this session? The user will be logged out immediately.</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance Settings</h2>

            <!-- Theme -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language" class="form-input">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="live-preview @GetPreviewClasses()">
                <h4>Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A preview card showing theme, font size, and layout options.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}
"}

